// Bring in the Verus prelude:
use vstd::prelude::*;

verus! {

    /// Given a non‐empty slice `a`, return some index of a maximum element.
    /// Spec:
    ///   - requires: a.len() > 0
    ///   - ensures:  result < a.len()
    ///             && forall j < a.len(): a[result] >= a[j]
    pub fn find_max(a: &[i32]) -> usize
        requires a.len() > 0
        ensures |result: usize| result < a.len() 
                        && forall(|j: usize| j < a.len() ==> a[result] >= a[j])
    {
        // Start with the first element as the current max.
        let mut best: usize = 0;
        // We will scan from i=1 up to a.len()-1.
        let mut i: usize = 1;
        while i < a.len() {
            // Invariant: best is a valid index.
            invariant best < a.len();
            // Invariant: i stays within [0..=a.len()].
            invariant i <= a.len();
            // Invariant: best is the index of a maximum in the prefix [0..i).
            invariant forall(|j: usize| j < i ==> a[best] >= a[j]);
            // We make progress by incrementing i.
            decreases a.len() - i;

            if a[i] > a[best] {
                best = i;
            }
            i += 1;
        }

        // By the invariant at loop exit (i == a.len()), best is a max over [0..a.len()).
        best
    }

} // end verus!